PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE analytics_parse_cache (
    harness        TEXT PRIMARY KEY,       -- claude/opencode/codex/vibe/kimi
    parser_version TEXT NOT NULL,          -- pin: mismatch = cache miss
    payload        TEXT NOT NULL,          -- JSON, parser-owned shape
    updated_at     TEXT
);
CREATE TABLE conversation_events (
    event_id                INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id         TEXT NOT NULL
                            REFERENCES conversations(conversation_id),
    sequence                INTEGER NOT NULL CHECK (sequence > 0),
    event_type              TEXT NOT NULL CHECK (trim(event_type) <> ''),
    payload_version         INTEGER NOT NULL DEFAULT 1
                            CHECK (payload_version > 0),
    payload                 TEXT NOT NULL DEFAULT '{}'
                            CHECK (
                              json_valid(payload)
                              AND json_type(payload)='object'
                              AND length(payload) <= 262144
                            ),
    message_id              INTEGER
                            REFERENCES conversation_messages(message_id),
    run_id                  INTEGER REFERENCES conversation_runs(run_id),
    created_at              TEXT NOT NULL DEFAULT (datetime('now')),
    UNIQUE (conversation_id, sequence)
);
