CREATE TABLE interface_sessions (
    session_id           INTEGER PRIMARY KEY AUTOINCREMENT,
    shell_id             INTEGER NOT NULL REFERENCES shells(shell_id),
    generation           INTEGER NOT NULL CHECK (generation > 0),
    archive_id           INTEGER REFERENCES shell_memory_archives(archive_id),
    harness              TEXT,               -- claude/codex/kimi
    model_route          TEXT,
    cli_version          TEXT,
    worktree             TEXT,
    tmux_socket          TEXT,               -- volatile; snapshot-excluded
    tmux_session         TEXT,
    tmux_window          TEXT,
    tmux_pane_id         TEXT,               -- immutable tmux pane id
    pane_pid             INTEGER,            -- volatile; snapshot-excluded
    pane_start_ticks    INTEGER,            -- volatile; snapshot-excluded
    harness_pid          INTEGER,            -- volatile; snapshot-excluded
    harness_start_ticks INTEGER,            -- volatile; snapshot-excluded
    occupancy            TEXT NOT NULL DEFAULT 'reserved'
                         CHECK (occupancy IN
                             ('reserved','occupied','unreconciled','ended')),
    lifecycle            TEXT NOT NULL DEFAULT 'starting'
                         CHECK (lifecycle IN
                             ('starting','idle','busy','approval','user_input',
                              'stopping','lost','error','ended')),
    reservation_expires_at TEXT,
    created_at           TEXT NOT NULL DEFAULT (datetime('now')),
    occupied_at          TEXT,
    ended_at             TEXT,
    end_reason           TEXT,
    error_detail         TEXT, graceful_timed_out_at TEXT, provider_ready_at TEXT, title TEXT, launch_effort TEXT, process_ready_at TEXT,
    -- graceful_timed_out_at TEXT — force-gate stamp, migration 0080.
    -- provider_ready_at TEXT — REAL provider readiness stamp (provider
    -- session_start hook; the wake gate's quiet baseline, flag #49),
    -- migration 0081. process_ready_at TEXT — the strictly WEAKER proof:
    -- the entrypoint's pre-exec claim, i.e. the PROCESS is up but the
    -- provider is unproven (migration 0113, flag #303). Never conflate the
    -- two: provider_ready_at set = provider handshaked; process_ready_at set
    -- with provider_ready_at NULL = process ready, provider UNPROVEN.
    -- These ride the migration-only ADD COLUMN precedent
    -- (schema.sql + migrations both apply on rebuild — never inline).
    -- title TEXT — chat title, client-minted once from the first composer
    -- message (60-char cap, set-if-unset); launch_effort TEXT — the effort
    -- the session was launched with, for U7's +Chat relaunch. Migration 0093.
    UNIQUE (shell_id, generation),
    FOREIGN KEY (shell_id, generation)
        REFERENCES interface_generations(shell_id, generation)
);
INSERT INTO "interface_sessions" VALUES(370,11,1,43,'claude','claude:planner','1.0.0','/tmp/interface','/tmp/tmux.sock','planner-session','shell','%1',5001,6001,5002,6002,'occupied','idle',NULL,'2026-07-31 00:00:00','2026-07-31 00:00:00',NULL,NULL,NULL,NULL,'2026-07-31 00:00:00','Disposable Interface session','high','2026-07-31 00:00:00');
CREATE TABLE interface_writer_leases (
    lease_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id     INTEGER NOT NULL REFERENCES interface_sessions(session_id),
    shell_id       INTEGER NOT NULL,
    generation     INTEGER NOT NULL,
    client_id      TEXT NOT NULL,            -- browser tab / CLI instance id
    token_hash     TEXT NOT NULL,            -- volatile credential hash
    next_input_seq INTEGER NOT NULL DEFAULT 1, -- expected monotonic client seq
    heartbeat_at   TEXT,                     -- volatile
    acquired_at    TEXT NOT NULL DEFAULT (datetime('now')),
    revoked_at     TEXT,
    revoke_reason  TEXT,
    FOREIGN KEY (shell_id, generation)
        REFERENCES interface_generations(shell_id, generation)
);
