CREATE TABLE planner_alerts (
    alert_id    INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id  INTEGER REFERENCES interface_sessions(session_id),
    binding_id  INTEGER REFERENCES sprint_planner_bindings(binding_id),
    message_id  INTEGER REFERENCES shell_messages(message_id),
    watch_id    INTEGER REFERENCES watched_prs(watch_id),
    severity    TEXT NOT NULL CHECK (severity IN ('info','warning','critical')),
    reason      TEXT NOT NULL,
    dedupe_key  TEXT NOT NULL,           -- app-computed: refs + reason
    opened_at   TEXT NOT NULL DEFAULT (datetime('now')),
    resolved_at TEXT
, acknowledged_at TEXT, acknowledged_by TEXT, sprint_doc_id INTEGER REFERENCES documents(document_id), unit_id INTEGER REFERENCES sprint_units(unit_id), role TEXT CHECK (role IN ('dev', 'reviewer', 'planner')), signal TEXT, shell_id INTEGER REFERENCES shells(shell_id), batch_id INTEGER
    REFERENCES planner_wake_batches(batch_id), detail TEXT);
