CREATE TABLE session_token_usage (
    usage_id            INTEGER PRIMARY KEY,
    archive_id          INTEGER REFERENCES shell_memory_archives(archive_id),  -- NULL = unattributed
    shell_id            INTEGER,                -- denormalized for filtering
    harness             TEXT    NOT NULL,       -- claude/opencode/codex/vibe/kimi
    harness_session_ref TEXT    NOT NULL,       -- transcript path / session id / rollout file / session dir
    provider            TEXT,
    model               TEXT,
    title               TEXT,                   -- native session title, or first-prompt derived
    started_at          TEXT,                   -- ISO UTC, from harness data
    ended_at            TEXT,                   -- ISO UTC, from harness data
    input_tokens        INTEGER,                -- fresh (uncached) input
    output_tokens       INTEGER,
    cache_read_tokens   INTEGER,
    cache_write_tokens  INTEGER,
    reasoning_tokens    INTEGER,                -- opencode + codex expose it
    status              TEXT    NOT NULL DEFAULT 'ok'
                        CHECK (status IN ('ok', 'partial', 'no_usage')),
    parser_version      TEXT,                   -- per-parser format pin
    captured_at         TEXT,                   -- sweep time, ISO UTC
    UNIQUE (harness, harness_session_ref, model)
);
CREATE TABLE shell_decisions (
    decision_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    shell_id           INTEGER NOT NULL REFERENCES shells(shell_id),
    decision_date      DATE    NOT NULL,
    priority           TEXT    NOT NULL DEFAULT 'M' CHECK(priority IN ('M','m')),
    decision           TEXT    NOT NULL,
    rationale          TEXT,
    parent_decision_id INTEGER REFERENCES shell_decisions(decision_id),
    is_deleted         INTEGER NOT NULL DEFAULT 0,
    created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
    -- feature_id  INTEGER REFERENCES roadmap(feature_id)   — the feature this
    -- document_id INTEGER REFERENCES documents(document_id) — decision shaped
    -- (the why-audit link), both added by migration 0047. Kept out of this
    -- baseline CREATE on purpose: ADD COLUMN can't be IF NOT EXISTS and rebuild
    -- applies migrations after schema.sql, so inlining would double-define.
    -- See migrations/0047_decisions_feature_link.sql.
, feature_id  INTEGER REFERENCES roadmap(feature_id), document_id INTEGER REFERENCES documents(document_id));
