    active_archive_id INTEGER,
    user_id           INTEGER REFERENCES users(user_id),
    is_shared         INTEGER NOT NULL DEFAULT 0,
    is_deleted        INTEGER NOT NULL DEFAULT 0
, api_key            TEXT, api_key_rotated_at TEXT, lns_curated_at TEXT);
