CREATE TABLE "spec_tasks" (
    task_id        INTEGER PRIMARY KEY AUTOINCREMENT,
    feature_id     INTEGER NOT NULL REFERENCES roadmap(feature_id),
    document_id    INTEGER NOT NULL REFERENCES documents(document_id),
    seq            INTEGER NOT NULL,
    title          TEXT    NOT NULL,
    description    TEXT,
    status         TEXT    NOT NULL DEFAULT 'pending'
                   CHECK(status IN ('pending','in_progress','done','cancelled')),
    completed_date DATE,
    resolution_notes TEXT,               -- why a cancelled task ended (mirrors flags)
    shell_id       INTEGER REFERENCES shells(shell_id),
    created_date   DATE    NOT NULL DEFAULT (date('now')),
    UNIQUE(document_id, seq)
);
CREATE TABLE sprint_assignment_results (
    result_id       INTEGER PRIMARY KEY AUTOINCREMENT,
    binding_id      INTEGER NOT NULL UNIQUE
                    REFERENCES sprint_conversation_bindings(binding_id),
    message_id      INTEGER NOT NULL UNIQUE
                    REFERENCES shell_messages(message_id),
    result_kind     TEXT NOT NULL
                    CHECK (length(trim(result_kind)) BETWEEN 1 AND 64),
    directive_id    INTEGER UNIQUE REFERENCES directives(directive_id),
    created_at      TEXT NOT NULL DEFAULT (datetime('now'))
);
