CREATE TRIGGER trg_conductor_skill_pack_insert
BEFORE INSERT ON flavor_skills
WHEN NEW.flavor = 'conductor' AND NEW.skill_id NOT IN (
    SELECT skill_id FROM skills
    WHERE name = 'sprint_cond' AND is_deleted = 0
)
BEGIN
    SELECT RAISE(IGNORE);
END;
CREATE TRIGGER trg_conversation_events_append_only_delete
BEFORE DELETE ON conversation_events
BEGIN
  SELECT RAISE(ABORT, 'conversation events are append-only');
END;
CREATE TRIGGER trg_conversation_events_append_only_update
BEFORE UPDATE ON conversation_events
BEGIN
  SELECT RAISE(ABORT, 'conversation events are append-only');
END;
CREATE TRIGGER trg_conversation_events_links_insert
BEFORE INSERT ON conversation_events
WHEN (
    NEW.message_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM conversation_messages m
      WHERE m.message_id=NEW.message_id
        AND m.conversation_id=NEW.conversation_id
    )
) OR (
    NEW.run_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM conversation_runs r
      WHERE r.run_id=NEW.run_id
        AND r.conversation_id=NEW.conversation_id
    )
)
BEGIN
  SELECT RAISE(ABORT, 'conversation event links do not share a conversation');
END;
CREATE TRIGGER trg_conversation_git_targets_identity_immutable
BEFORE UPDATE OF
    target_id, conversation_id, branch_name, first_head_sha, first_seen_at
ON conversation_git_targets
BEGIN
  SELECT RAISE(ABORT, 'conversation Git target identity is immutable');
END;
CREATE TRIGGER trg_conversation_git_targets_pr_immutable
BEFORE UPDATE OF pr_number ON conversation_git_targets
WHEN OLD.pr_number IS NOT NULL
  AND NEW.pr_number IS NOT OLD.pr_number
BEGIN
  SELECT RAISE(ABORT, 'conversation Git target PR identity is immutable');
END;
CREATE TRIGGER trg_conversation_messages_cause_insert
BEFORE INSERT ON conversation_messages
WHEN NEW.caused_by_message_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM conversation_messages cause
    WHERE cause.message_id=NEW.caused_by_message_id
      AND cause.conversation_id=NEW.conversation_id
)
BEGIN
  SELECT RAISE(ABORT, 'causal message does not belong to conversation');
END;
CREATE TRIGGER trg_conversation_messages_immutable
BEFORE UPDATE OF
    message_id, conversation_id, sender_kind, sender_ref, message_kind,
    body, idempotency_key, request_hash, caused_by_message_id, created_at
ON conversation_messages
BEGIN
  SELECT RAISE(ABORT, 'conversation message identity and content are immutable');
END;
CREATE TRIGGER trg_conversation_messages_state
BEFORE UPDATE OF state ON conversation_messages
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state='accepted' AND NEW.state IN
        ('queued','running','completed','failed','cancelled')) OR
    (OLD.state='queued'   AND NEW.state IN
        ('running','failed','cancelled')) OR
    (OLD.state='running'  AND NEW.state IN
        ('completed','failed','cancelled'))
    -- completed, failed, and cancelled are terminal.
)
BEGIN
  SELECT RAISE(ABORT, 'illegal conversation message transition');
END;
CREATE TRIGGER trg_conversation_outbox_identity_immutable
BEFORE UPDATE OF outbox_id, conversation_id, message_id, created_at
ON conversation_outbox
BEGIN
  SELECT RAISE(ABORT, 'conversation outbox identity is immutable');
END;
CREATE TRIGGER trg_conversation_outbox_links_insert
BEFORE INSERT ON conversation_outbox
WHEN (
  NOT EXISTS (
    SELECT 1 FROM conversation_messages m
    WHERE m.message_id=NEW.message_id
      AND m.conversation_id=NEW.conversation_id
  )
) OR (
  NEW.run_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM conversation_runs r
    WHERE r.run_id=NEW.run_id
      AND r.conversation_id=NEW.conversation_id
      AND r.trigger_message_id=NEW.message_id
  )
)
BEGIN
  SELECT RAISE(ABORT, 'conversation outbox links do not share a message');
END;
CREATE TRIGGER trg_conversation_outbox_run_update
BEFORE UPDATE OF run_id ON conversation_outbox
WHEN NEW.run_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM conversation_runs r
    WHERE r.run_id=NEW.run_id
      AND r.conversation_id=NEW.conversation_id
      AND r.trigger_message_id=NEW.message_id
)
BEGIN
  SELECT RAISE(ABORT, 'conversation outbox run does not match message');
END;
CREATE TRIGGER trg_conversation_outbox_state
BEFORE UPDATE OF state ON conversation_outbox
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state='pending' AND NEW.state IN ('claimed','cancelled')) OR
    (OLD.state='claimed' AND NEW.state IN
        ('pending','dispatched','cancelled'))
    -- dispatched and cancelled are terminal.
)
BEGIN
  SELECT RAISE(ABORT, 'illegal conversation outbox transition');
END;
CREATE TRIGGER trg_conversation_runs_links_insert
BEFORE INSERT ON conversation_runs
WHEN NOT EXISTS (
    SELECT 1
    FROM conversations c
    JOIN conversation_messages m
      ON m.conversation_id=c.conversation_id
    WHERE c.conversation_id=NEW.conversation_id
      AND c.shell_id=NEW.shell_id
      AND m.message_id=NEW.trigger_message_id
)
BEGIN
  SELECT RAISE(ABORT, 'conversation run links do not share a conversation');
END;
CREATE TRIGGER trg_conversation_runs_links_update
BEFORE UPDATE OF conversation_id, shell_id, trigger_message_id
ON conversation_runs
BEGIN
  SELECT RAISE(ABORT, 'conversation run identity is immutable');
END;
CREATE TRIGGER trg_conversation_runs_state
BEFORE UPDATE OF state ON conversation_runs
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state='leased' AND NEW.state IN
        ('starting','failed','cancelled','unknown')) OR
    (OLD.state='starting' AND NEW.state IN
        ('running','failed','cancelled','unknown')) OR
    (OLD.state='running' AND NEW.state IN
        ('succeeded','failed','cancelled','unknown'))
    -- terminal run states have no exits.
)
BEGIN
  SELECT RAISE(ABORT, 'illegal conversation run transition');
END;
CREATE TRIGGER trg_conversations_identity_immutable
BEFORE UPDATE OF
    conversation_id, shell_id, mode, owner_user_id, sprint_doc_id,
    harness, provider, model, effort, worktree,
    creation_idempotency_key, creation_request_hash, created_at
ON conversations
BEGIN
  SELECT RAISE(ABORT, 'conversation identity and route are immutable');
END;
CREATE TRIGGER trg_conversations_state
BEFORE UPDATE OF state ON conversations
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state='idle'    AND NEW.state IN ('queued','closed')) OR
    (OLD.state='queued'  AND NEW.state IN ('idle','running')) OR
    (OLD.state='running' AND NEW.state IN
        ('idle','queued','waiting','error')) OR
    (OLD.state='waiting' AND NEW.state IN ('queued','closed')) OR
    (OLD.state='error'   AND NEW.state IN ('queued','closed'))
    -- closed is terminal.
)
BEGIN
  SELECT RAISE(ABORT, 'illegal conversation transition');
END;
CREATE TRIGGER trg_directive_issuer_insert
BEFORE INSERT ON directives
WHEN NOT (
    (NEW.issuer_flavor='system' AND NEW.issuer_shell_id IS NULL)
    OR
    (NEW.issuer_flavor<>'system' AND NEW.issuer_shell_id IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM shells s
       WHERE s.shell_id=NEW.issuer_shell_id
         AND s.flavor=NEW.issuer_flavor
         AND COALESCE(s.is_deleted,0)=0
     ))
)
BEGIN
  SELECT RAISE(ABORT, 'directive issuer does not match shell flavor');
END;
CREATE TRIGGER trg_directive_issuer_update
BEFORE UPDATE OF issuer_shell_id, issuer_flavor, kind ON directives
BEGIN
  SELECT RAISE(ABORT, 'directive issuer and kind are immutable');
END;
CREATE TRIGGER trg_directive_link_update
BEFORE UPDATE OF sprint_doc_id, unit_id ON directives
WHEN NEW.unit_id IS NOT NULL AND (
    NEW.sprint_doc_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM sprint_units u
      WHERE u.unit_id=NEW.unit_id
        AND u.sprint_doc_id=NEW.sprint_doc_id
    )
)
BEGIN
  SELECT RAISE(ABORT, 'directive unit does not belong to sprint');
END;
CREATE TRIGGER trg_directive_unit_insert
BEFORE INSERT ON directives
WHEN NEW.unit_id IS NOT NULL AND (
    NEW.sprint_doc_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM sprint_units u
      WHERE u.unit_id=NEW.unit_id
        AND u.sprint_doc_id=NEW.sprint_doc_id
    )
)
BEGIN
  SELECT RAISE(ABORT, 'directive unit does not belong to sprint');
END;
CREATE TRIGGER trg_interface_input_composer
BEFORE UPDATE OF composer ON interface_input_state
WHEN NEW.composer <> OLD.composer AND NOT (
    (OLD.composer = 'unknown' AND NEW.composer IN ('clean','dirty')) OR
    (OLD.composer = 'clean'   AND NEW.composer IN ('dirty','unknown')) OR
    (OLD.composer = 'dirty'   AND NEW.composer IN ('clean','unknown'))
)
BEGIN
  SELECT RAISE(ABORT, 'illegal composer transition');
END;
CREATE TRIGGER trg_interface_input_delivery
BEFORE UPDATE OF delivery ON interface_input_state
WHEN NEW.delivery <> OLD.delivery AND NOT (
    (OLD.delivery = 'normal'           AND NEW.delivery = 'delivery_unknown') OR
    (OLD.delivery = 'delivery_unknown' AND NEW.delivery = 'normal')
)
BEGIN
  SELECT RAISE(ABORT, 'illegal delivery transition');
END;
CREATE TRIGGER trg_interface_sessions_lifecycle
BEFORE UPDATE OF lifecycle ON interface_sessions
WHEN NEW.lifecycle <> OLD.lifecycle AND NOT (
    (OLD.lifecycle = 'starting'   AND NEW.lifecycle IN ('idle','stopping','lost','error','ended')) OR
    (OLD.lifecycle = 'idle'       AND NEW.lifecycle IN ('busy','stopping','lost')) OR
    (OLD.lifecycle = 'busy'       AND NEW.lifecycle IN ('idle','approval','user_input','error','stopping','lost')) OR
    (OLD.lifecycle = 'approval'   AND NEW.lifecycle IN ('busy','error','stopping','lost')) OR
    (OLD.lifecycle = 'user_input' AND NEW.lifecycle IN ('busy','error','stopping','lost')) OR
    (OLD.lifecycle = 'stopping'   AND NEW.lifecycle IN ('ended','lost','error')) OR
    (OLD.lifecycle = 'lost'       AND NEW.lifecycle IN ('ended','stopping')) OR
    (OLD.lifecycle = 'error'      AND NEW.lifecycle IN ('ended','stopping'))
)
BEGIN
  SELECT RAISE(ABORT, 'illegal interface lifecycle transition');
END;
CREATE TRIGGER trg_interface_sessions_occupancy
BEFORE UPDATE OF occupancy ON interface_sessions
WHEN NEW.occupancy <> OLD.occupancy AND NOT (
    (OLD.occupancy = 'reserved'     AND NEW.occupancy IN ('occupied','unreconciled','ended')) OR
    (OLD.occupancy = 'occupied'     AND NEW.occupancy IN ('unreconciled','ended')) OR
    (OLD.occupancy = 'unreconciled' AND NEW.occupancy IN ('occupied','ended'))
)
BEGIN
  SELECT RAISE(ABORT, 'illegal interface occupancy transition');
END;
CREATE TRIGGER trg_par_state
BEFORE UPDATE OF state ON planner_action_receipts
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state = 'intent'  AND NEW.state IN ('complete','unknown')) OR
    (OLD.state = 'unknown' AND NEW.state = 'reconciled')
)
BEGIN
  SELECT RAISE(ABORT, 'illegal action receipt transition');
END;
CREATE TRIGGER trg_pwb_state
BEFORE UPDATE OF state ON planner_wake_batches
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state = 'queued'           AND NEW.state IN ('submitting','complete')) OR
    (OLD.state = 'submitting'       AND NEW.state IN ('queued','running','delivery_unknown')) OR
    (OLD.state = 'running'          AND NEW.state IN ('complete','delivery_unknown')) OR
    (OLD.state = 'delivery_unknown' AND NEW.state = 'complete')
)
BEGIN
  SELECT RAISE(ABORT, 'illegal wake batch transition');
END;
CREATE TRIGGER trg_pwi_state
BEFORE UPDATE OF state ON planner_wake_items
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state = 'queued'      AND NEW.state IN ('batched','done','quarantined','cancelled')) OR
    (OLD.state = 'batched'     AND NEW.state IN ('queued','submitting','cancelled')) OR
    (OLD.state = 'submitting'  AND NEW.state IN ('queued','running','cancelled')) OR
    (OLD.state = 'running'     AND NEW.state IN ('done','reconcile','queued','quarantined','cancelled')) OR
    (OLD.state = 'reconcile'   AND NEW.state IN ('queued','done','cancelled')) OR
    (OLD.state = 'quarantined' AND NEW.state IN ('queued','cancelled'))
)
BEGIN
  SELECT RAISE(ABORT, 'illegal wake item transition');
END;
CREATE TRIGGER trg_sentinel_events_append_only_delete
BEFORE DELETE ON sentinel_events
BEGIN
  SELECT RAISE(ABORT, 'sentinel_events is append-only');
END;
CREATE TRIGGER trg_sentinel_events_append_only_update
BEFORE UPDATE ON sentinel_events
BEGIN
  SELECT RAISE(ABORT, 'sentinel_events is append-only');
END;
CREATE TRIGGER trg_sentinel_events_unit_insert
BEFORE INSERT ON sentinel_events
WHEN NEW.unit_id IS NOT NULL AND (
    NEW.sprint_doc_id IS NULL OR NOT EXISTS (
      SELECT 1 FROM sprint_units u
      WHERE u.unit_id=NEW.unit_id
        AND u.sprint_doc_id=NEW.sprint_doc_id
    )
)
BEGIN
  SELECT RAISE(ABORT, 'sentinel event unit does not belong to sprint');
END;
CREATE TRIGGER trg_shells_current_state_len
BEFORE UPDATE OF current_state ON shells
WHEN LENGTH(COALESCE(NEW.current_state, '')) > 300
BEGIN
  SELECT RAISE(ABORT, 'current_state over 300 chars — name what is in flight and point at the row (doc/feature/flag/decision id), do not reproduce it');
END;
CREATE TRIGGER trg_sie_cap_lns
BEFORE INSERT ON shell_identity_entries
WHEN NEW.kind = 'lns' AND (
  SELECT COUNT(*) FROM shell_identity_entries
  WHERE shell_id = NEW.shell_id AND kind='lns'
    AND is_deleted=0 AND retired_at IS NULL
) >= 20
BEGIN
  SELECT RAISE(ABORT, 'L&S cap (20) reached for this shell — retire an entry first');
END;
CREATE TRIGGER trg_sie_cap_seed
BEFORE INSERT ON shell_identity_entries
WHEN NEW.kind = 'seed' AND (
  SELECT COUNT(*) FROM shell_identity_entries
  WHERE shell_id = NEW.shell_id AND kind='seed'
    AND is_deleted=0 AND retired_at IS NULL
) >= 10
BEGIN
  SELECT RAISE(ABORT, 'seed cap (10) reached for this shell — retire an entry first');
END;
CREATE TRIGGER trg_sie_len_lns
BEFORE INSERT ON shell_identity_entries
WHEN NEW.kind = 'lns' AND LENGTH(NEW.body) > 500
     AND NEW.created_at >= datetime('now', '-300 seconds')
BEGIN
  SELECT RAISE(ABORT, 'L&S entry over 500 chars — an L&S entry is the RULE; the incident goes to the narrative (sc mem narrative), then state the rule alone');
END;
CREATE TRIGGER trg_singleton_cartographer
BEFORE INSERT ON shells
WHEN NEW.flavor = 'cartographer' AND (
  SELECT COUNT(*) FROM shells
  WHERE flavor = 'cartographer' AND is_deleted = 0
) >= 1
BEGIN
  SELECT RAISE(ABORT, 'cartographer is a singleton — this fork already has one');
END;
CREATE TRIGGER trg_singleton_conductor
BEFORE INSERT ON shells
WHEN NEW.flavor = 'conductor' AND NEW.is_deleted = 0 AND (
    SELECT COUNT(*) FROM shells
    WHERE flavor = 'conductor' AND is_deleted = 0
) >= 1
BEGIN
    SELECT RAISE(
        ABORT,
        'conductor is a singleton — this fork already has one'
    );
END;
CREATE TRIGGER trg_spec_qaqc_reviews_append_only_delete
BEFORE DELETE ON spec_qaqc_reviews
BEGIN
  SELECT RAISE(ABORT, 'spec_qaqc_reviews is append-only');
END;
CREATE TRIGGER trg_spec_qaqc_reviews_append_only_update
BEFORE UPDATE ON spec_qaqc_reviews
BEGIN
  SELECT RAISE(ABORT, 'spec_qaqc_reviews is append-only');
END;
CREATE TRIGGER trg_spec_qaqc_reviews_reviewer_insert
BEFORE INSERT ON spec_qaqc_reviews
WHEN NOT EXISTS (
  SELECT 1 FROM shells s
  WHERE s.shell_id=NEW.reviewer_shell_id
    AND s.flavor='reviewer'
    AND COALESCE(s.is_deleted,0)=0
)
BEGIN
  SELECT RAISE(ABORT, 'QAQC actor must be an active reviewer shell');
END;
CREATE TRIGGER trg_spec_qaqc_reviews_spec_insert
BEFORE INSERT ON spec_qaqc_reviews
WHEN NOT EXISTS (
  SELECT 1 FROM documents d
  WHERE d.document_id=NEW.spec_doc_id AND d.kind='spec'
)
BEGIN
  SELECT RAISE(ABORT, 'QAQC target must be a spec document');
END;
CREATE TRIGGER trg_sprint_assignment_result_links_insert
BEFORE INSERT ON sprint_assignment_results
WHEN NOT EXISTS (
  SELECT 1
  FROM sprint_conversation_bindings b
  JOIN conversations c ON c.conversation_id=b.conversation_id
  JOIN shell_messages m ON m.message_id=NEW.message_id
  LEFT JOIN directives d ON d.directive_id=NEW.directive_id
  WHERE b.binding_id=NEW.binding_id
    AND b.lifecycle='one_shot'
    AND b.state='active'
    AND b.required_result_kind=NEW.result_kind
    AND m.kind='result'
    AND m.sprint_doc_id=b.sprint_doc_id
    AND m.from_shell_id=c.shell_id
    AND (
      (
        NEW.result_kind='abort-report'
        AND NEW.directive_id IS NULL
        AND EXISTS (
          SELECT 1 FROM sprint_cancellations cancel
          WHERE cancel.sprint_doc_id=b.sprint_doc_id
            AND cancel.state='completed'
            AND cancel.completed_by_shell_id=c.shell_id
        )
      )
      OR
      (
        NEW.result_kind<>'abort-report'
        AND NEW.directive_id IS NOT NULL
        AND d.sprint_doc_id=b.sprint_doc_id
        AND d.unit_id IS b.unit_id
        AND d.issuer_shell_id=c.shell_id
        AND d.target='conductor'
        AND d.status='pending'
        AND (
          (b.role='planner' AND d.issuer_flavor='planner')
          OR (b.role='developer' AND d.issuer_flavor='dev')
          OR (
            b.role IN ('reviewer','conformance')
            AND d.issuer_flavor='reviewer'
          )
        )
      )
    )
)
BEGIN
  SELECT RAISE(
    ABORT,
    'Sprint assignment result does not match its binding, message, or directive'
  );
END;
CREATE TRIGGER trg_sprint_assignment_results_append_only_delete
BEFORE DELETE ON sprint_assignment_results
BEGIN
  SELECT RAISE(ABORT, 'Sprint assignment results are append-only');
END;
CREATE TRIGGER trg_sprint_assignment_results_append_only_update
BEFORE UPDATE ON sprint_assignment_results
BEGIN
  SELECT RAISE(ABORT, 'Sprint assignment results are append-only');
END;
CREATE TRIGGER trg_sprint_cancellation_completion
BEFORE UPDATE OF state ON sprint_cancellations
WHEN NEW.state='completed' AND OLD.state='requested' AND NOT EXISTS (
  SELECT 1
  FROM sprints sp
  JOIN shells planner ON planner.shell_id=NEW.completed_by_shell_id
  WHERE sp.sprint_doc_id=NEW.sprint_doc_id
    AND sp.planner_shell_id=NEW.completed_by_shell_id
    AND planner.flavor='planner'
    AND COALESCE(planner.is_deleted,0)=0
)
BEGIN
  SELECT RAISE(
    ABORT,
    'Sprint cancellation must be completed by its originating Planner'
  );
END;
CREATE TRIGGER trg_sprint_cancellation_delete
BEFORE DELETE ON sprint_cancellations
BEGIN
  SELECT RAISE(ABORT, 'Sprint cancellations are durable history');
END;
CREATE TRIGGER trg_sprint_cancellation_identity_immutable
BEFORE UPDATE OF
    cancellation_id, sprint_doc_id, requested_by_user_id, reason,
    source_directive_id, planner_conversation_id, requested_at
ON sprint_cancellations
BEGIN
  SELECT RAISE(ABORT, 'Sprint cancellation identity is immutable');
END;
CREATE TRIGGER trg_sprint_cancellation_links_insert
BEFORE INSERT ON sprint_cancellations
WHEN NOT EXISTS (
  SELECT 1
  FROM sprints sp
  JOIN directives d
    ON d.directive_id=NEW.source_directive_id
  JOIN conversations c
    ON c.conversation_id=NEW.planner_conversation_id
  JOIN sprint_conversation_bindings b
    ON b.conversation_id=c.conversation_id
  WHERE sp.sprint_doc_id=NEW.sprint_doc_id
    AND (
      (NEW.state='requested' AND sp.state IN ('declared','active'))
      OR
      (NEW.state='completed' AND sp.state='aborted')
    )
    AND d.sprint_doc_id=NEW.sprint_doc_id
    AND d.issuer_flavor='system'
    AND d.kind='cancel'
    AND d.target='planner'
    AND d.status='executed'
    AND c.mode='sprint'
    AND c.sprint_doc_id=NEW.sprint_doc_id
    AND b.sprint_doc_id=NEW.sprint_doc_id
    AND b.role='planner'
    AND b.lifecycle='one_shot'
    AND b.source_directive_id=NEW.source_directive_id
)
BEGIN
  SELECT RAISE(
    ABORT,
    'Sprint cancellation links must name its executed cancel directive and Planner conversation'
  );
END;
CREATE TRIGGER trg_sprint_cancellation_state
BEFORE UPDATE OF state ON sprint_cancellations
WHEN NEW.state<>OLD.state AND NOT (
  OLD.state='requested' AND NEW.state='completed'
)
BEGIN
  SELECT RAISE(ABORT, 'illegal Sprint cancellation transition');
END;
CREATE TRIGGER trg_sprint_cancellation_terminal_immutable
BEFORE UPDATE OF
    state, abort_report, completed_by_shell_id, completed_at
ON sprint_cancellations
WHEN OLD.state='completed'
BEGIN
  SELECT RAISE(ABORT, 'completed Sprint cancellation is immutable');
END;
CREATE TRIGGER trg_sprint_conversation_binding_delete
BEFORE DELETE ON sprint_conversation_bindings
BEGIN
  SELECT RAISE(ABORT, 'Sprint conversation bindings are durable history');
END;
CREATE TRIGGER trg_sprint_conversation_binding_identity_immutable
BEFORE UPDATE OF
    binding_id, conversation_id, sprint_doc_id, role, lifecycle, slot, unit_id,
    source_directive_id, source_message_id, required_result_kind, created_at
ON sprint_conversation_bindings
BEGIN
  SELECT RAISE(ABORT, 'Sprint conversation binding identity is immutable');
END;
CREATE TRIGGER trg_sprint_conversation_binding_links_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NOT EXISTS (
  SELECT 1
  FROM conversations c
  JOIN shells s ON s.shell_id=c.shell_id
  WHERE c.conversation_id=NEW.conversation_id
    AND c.mode='sprint'
    AND c.sprint_doc_id=NEW.sprint_doc_id
    AND COALESCE(s.is_deleted,0)=0
    AND s.shortname=NEW.slot
    AND (
      s.flavor=NEW.role
      OR (NEW.role='developer' AND s.flavor='dev')
      OR (NEW.role='conformance' AND s.flavor='reviewer')
    )
)
BEGIN
  SELECT RAISE(
    ABORT,
    'Sprint binding conversation, Sprint, role, or shell does not match'
  );
END;
CREATE TRIGGER trg_sprint_conversation_binding_message_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NEW.source_message_id IS NOT NULL AND NOT EXISTS (
  SELECT 1
  FROM shell_messages m
  JOIN conversations c ON c.conversation_id=NEW.conversation_id
  WHERE m.message_id=NEW.source_message_id
    AND m.sprint_doc_id=NEW.sprint_doc_id
    AND m.to_shell_id=c.shell_id
)
BEGIN
  SELECT RAISE(ABORT, 'Sprint binding source message does not match');
END;
CREATE TRIGGER trg_sprint_conversation_binding_result_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NEW.result_message_id IS NOT NULL AND NOT EXISTS (
  SELECT 1
  FROM shell_messages m
  JOIN conversations c ON c.conversation_id=NEW.conversation_id
  WHERE m.message_id=NEW.result_message_id
    AND m.sprint_doc_id=NEW.sprint_doc_id
    AND m.kind='result'
    AND m.from_shell_id=c.shell_id
)
BEGIN
  SELECT RAISE(ABORT, 'Sprint binding result message does not match');
END;
CREATE TRIGGER trg_sprint_conversation_binding_result_update
BEFORE UPDATE OF result_message_id ON sprint_conversation_bindings
WHEN NEW.result_message_id IS NOT NULL AND NOT EXISTS (
  SELECT 1
  FROM shell_messages m
  JOIN conversations c ON c.conversation_id=NEW.conversation_id
  WHERE m.message_id=NEW.result_message_id
    AND m.sprint_doc_id=NEW.sprint_doc_id
    AND m.kind='result'
    AND m.from_shell_id=c.shell_id
)
BEGIN
  SELECT RAISE(ABORT, 'Sprint binding result message does not match');
END;
CREATE TRIGGER trg_sprint_conversation_binding_source_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NEW.source_directive_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM directives d
  WHERE d.directive_id=NEW.source_directive_id
    AND d.sprint_doc_id=NEW.sprint_doc_id
)
BEGIN
  SELECT RAISE(ABORT, 'Sprint binding source directive does not match');
END;
CREATE TRIGGER trg_sprint_conversation_binding_state
BEFORE UPDATE OF state ON sprint_conversation_bindings
WHEN NEW.state<>OLD.state AND NOT (
  (OLD.state='pending' AND NEW.state IN ('active','terminal'))
  OR
  (OLD.state='active' AND NEW.state='terminal')
)
BEGIN
  SELECT RAISE(ABORT, 'illegal Sprint conversation binding transition');
END;
CREATE TRIGGER trg_sprint_conversation_binding_terminal_immutable
BEFORE UPDATE OF outcome, result_message_id, started_at, completed_at
ON sprint_conversation_bindings
WHEN OLD.state='terminal' AND (
  NEW.outcome IS NOT OLD.outcome
  OR NEW.result_message_id IS NOT OLD.result_message_id
  OR NEW.started_at IS NOT OLD.started_at
  OR NEW.completed_at IS NOT OLD.completed_at
)
BEGIN
  SELECT RAISE(ABORT, 'terminal Sprint conversation binding is immutable');
END;
CREATE TRIGGER trg_sprint_conversation_binding_terminal_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NEW.state='terminal' AND NOT EXISTS (
  SELECT 1 FROM conversations c
  WHERE c.conversation_id=NEW.conversation_id
    AND c.state='closed'
)
BEGIN
  SELECT RAISE(ABORT, 'terminal Sprint binding requires closed conversation');
END;
CREATE TRIGGER trg_sprint_conversation_binding_terminal_update
BEFORE UPDATE OF state ON sprint_conversation_bindings
WHEN NEW.state='terminal' AND OLD.state<>'terminal' AND NOT EXISTS (
  SELECT 1 FROM conversations c
  WHERE c.conversation_id=NEW.conversation_id
    AND c.state='closed'
)
BEGIN
  SELECT RAISE(ABORT, 'terminal Sprint binding requires closed conversation');
END;
CREATE TRIGGER trg_sprint_conversation_binding_unit_insert
BEFORE INSERT ON sprint_conversation_bindings
WHEN NEW.unit_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM sprint_units u
  WHERE u.unit_id=NEW.unit_id
    AND u.sprint_doc_id=NEW.sprint_doc_id
)
BEGIN
  SELECT RAISE(ABORT, 'Sprint binding unit does not belong to Sprint');
END;
CREATE TRIGGER trg_sprint_units_state
BEFORE UPDATE OF state ON sprint_units
WHEN NEW.state <> OLD.state AND NOT (
    (OLD.state = 'pending'   AND NEW.state IN ('working','cancelled')) OR
    (OLD.state = 'working'   AND NEW.state IN ('in_review','blocked','merged','cancelled')) OR
    (OLD.state = 'in_review' AND NEW.state IN ('working','blocked','merged','cancelled')) OR
    (OLD.state = 'blocked'   AND NEW.state IN ('working','cancelled'))
    -- 'merged' and 'cancelled' appear on no left-hand side: terminal.
)
BEGIN
  SELECT RAISE(ABORT, 'illegal sprint unit transition');
END;
CREATE TRIGGER trg_sprints_document_insert
BEFORE INSERT ON sprints
WHEN NOT EXISTS (
  SELECT 1 FROM documents d
  WHERE d.document_id=NEW.sprint_doc_id
    AND d.kind='doc'
    AND d.title LIKE 'SPRINT:%'
)
BEGIN
  SELECT RAISE(ABORT, 'sprint row requires a SPRINT: document');
END;
CREATE TRIGGER trg_sprints_identity_update
BEFORE UPDATE OF sprint_doc_id, spec_doc_id, planner_shell_id, qaqc_review_id,
                 planner_route, dev_route, reviewer_route, legacy
ON sprints
WHEN NOT (
  OLD.state='needs_owner'
  AND OLD.legacy=1
  AND NEW.sprint_doc_id=OLD.sprint_doc_id
  AND NEW.legacy=1
)
BEGIN
  SELECT RAISE(ABORT, 'declared sprint identity and routes are immutable');
END;
CREATE TRIGGER trg_sprints_review_insert
BEFORE INSERT ON sprints
WHEN NEW.qaqc_review_id IS NOT NULL AND NOT EXISTS (
  SELECT 1 FROM spec_qaqc_reviews q
  WHERE q.review_id=NEW.qaqc_review_id
    AND q.spec_doc_id=NEW.spec_doc_id
    AND q.verdict='approved'
)
BEGIN
  SELECT RAISE(ABORT, 'sprint QAQC review must approve its governing spec');
END;
CREATE TRIGGER trg_sprints_state_transition
BEFORE UPDATE OF state ON sprints
WHEN NEW.state<>OLD.state AND NOT (
  (OLD.state='needs_owner' AND NEW.state IN ('declared','closed','aborted'))
  OR (OLD.state='declared' AND NEW.state IN ('active','aborted'))
  OR (OLD.state='active' AND NEW.state IN ('closing','aborted'))
  OR (OLD.state='closing' AND NEW.state IN ('closed','aborted'))
)
BEGIN
  SELECT RAISE(ABORT, 'illegal sprint state transition');
END;
CREATE TRIGGER trg_wake_machine_retirements_append_only_delete
BEFORE DELETE ON wake_machine_retirements
BEGIN
  SELECT RAISE(ABORT, 'wake_machine_retirements is append-only');
END;
CREATE TRIGGER trg_wake_machine_retirements_append_only_update
BEFORE UPDATE ON wake_machine_retirements
BEGIN
  SELECT RAISE(ABORT, 'wake_machine_retirements is append-only');
END;
